        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]

        if len(cells) < 2:
            continue

        main_sums = set(r + c for r, c in cells)
        if len(main_sums) == 1:
            target = cells[0][0] + cells[0][1]

